"""Generates Rust sources from Linux rtw89 (GPL-2.0 OR BSD-3-Clause; used here under BSD-3-Clause):
register and field definitions (reg.h, mac.h, txrx.h, fw.h, phy.h, efuse.h, usb.h) for the RTL8912AU / RTL8922AU
port. Usage: python gen_rtw89.py <rtw89 dir> <out dir>"""
import re
import sys
from pathlib import Path

HEADER = """// Generated by crates/radio/tools/gen_rtw89.py from Linux rtw89 ({src}).
// Copyright(c) 2019-2025 Realtek Corporation. Used under the BSD-3-Clause license (see NOTICE.md).
// Do not edit.
"""


def genmask(h, l):
    return ((1 << (h + 1)) - 1) & ~((1 << l) - 1)


def c_expr_to_rust(expr, known):
    expr = expr.strip()
    expr = re.sub(r"\bBIT\((\d+)\)", r"(1u32 << \1)", expr)
    expr = re.sub(r"\bGENMASK\((\d+),\s*(\d+)\)", r"genmask(\1, \2)", expr)
    expr = re.sub(r"\b(0x[0-9A-Fa-f]+|\d+)[uUlL]+\b", r"\1", expr)
    expr = expr.replace("~", "!")
    for tok in re.findall(r"[A-Za-z_][A-Za-z0-9_]*", re.sub(r"\b0x[0-9A-Fa-f]+\b", "0", expr)):
        if tok in ("u32", "genmask"):
            continue
        if tok not in known:
            return None
    if re.search(r"[^\sA-Za-z0-9_()|&!<>+\-*x,]", expr):
        return None
    try:
        value = eval(expr.replace("1u32", "1").replace("!", "~"), {"__builtins__": {}, "genmask": genmask}, dict(known))
    except Exception:
        return None
    if not isinstance(value, int) or value < 0 or value > 0xFFFFFFFF:
        return None
    return expr, value


def gen_regs(srcs, out):
    text = "\n".join(s.read_text(encoding="utf-8") for s in srcs)
    text = re.sub(r"\\\n", " ", text)
    known, lines = {}, []
    for m in re.finditer(r"^#define\s+([A-Z][A-Z0-9_]*)\s+(.+?)\s*$", text, re.M):
        name, value = m.group(1), re.sub(r"/\*.*?\*/", "", m.group(2)).strip()
        if not value or name.startswith("__") or name in known:
            continue
        r = c_expr_to_rust(value, known)
        if r is None:
            continue
        rust, v = r
        known[name] = v
        lines.append(f"pub const {name}: u32 = {rust};")
    body = HEADER.format(src=", ".join(s.name for s in srcs)) + "#![allow(dead_code, unused_parens, clippy::all)]\n\n"
    body += "const fn genmask(h: u32, l: u32) -> u32 {\n    (u32::MAX >> (31 - h)) & !((1u32 << l) - 1)\n}\n\n"
    out.write_text(body + "\n".join(lines) + "\n", encoding="utf-8")
    return len(lines)


def main():
    src, out = Path(sys.argv[1]), Path(sys.argv[2])
    out.mkdir(parents=True, exist_ok=True)
    print("regs", gen_regs([src / n for n in ("reg.h", "mac.h", "txrx.h", "fw.h", "phy.h", "efuse.h", "usb.h")], out / "regs.rs"))


if __name__ == "__main__":
    main()
